"""Explicit, field-level follow-up facts; source contents reviewed by the author."""
from admissions_records import records,L,S,flush_ru,TR
from pathlib import Path
import json
OUT=Path('research/admissions-followup')
reviews=json.loads((OUT/'reviews.json').read_text(encoding='utf8')) if (OUT/'reviews.json').exists() else {}
def academic(uid,en,ru,url,label,remaining,policy=None,status='resolved-scoped',indices=None):
 rec=records[uid];before=[r['academic'].get('satPolicy') for r in rec['routes']]
 for i,r in enumerate(rec['routes']):
  if indices is not None and i not in indices:continue
  a=r['academic'];a['entryRequirements']=L(en,ru)
  if policy:
   a['satPolicy']=policy
   a['note']=None
  source=S(url,L(label,label.split(':')[0]+' — академические условия поступления'));r['sources']=list({s['url']:s for s in r['sources']+[source]}.values())
 rec['unknown']=[remaining];rec['stage']='followup-checked-awaiting-browser'
 reviews[uid]={'id':uid,'country':rec['country'],'status':status,'academicEntry':en,'source':url,'checked':'2026-11-19','scope':'International first-year bachelor; programme/qualification exceptions remain explicit; an undated active page does not by itself confirm Fall 2027.','beforePolicy':reviews.get(uid,{}).get('beforePolicy',before),'afterPolicy':[r['academic'].get('satPolicy') for r in rec['routes']],'remaining':remaining}
def finish():
 for rec in records.values():
  for r in rec['routes']:r['sources']=list({s['url']:s for s in r['sources']}.values())
 L('Academic entry requirements for this route','Академические условия поступления этого маршрута')
 L('School-leaving qualification, subjects and programme eligibility','Школьная квалификация, предметы и допуск к программе')
 L('Academic qualifications and other examinations','Академические квалификации и другие экзамены')
 L('See the verified route-specific academic entry requirements above.','См. проверенные академические условия соответствующего маршрута выше.')
 Path('research/admissions-120/requirements.json').write_text(json.dumps(records,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
 Path('data/requirements.js').write_text('/* Verified admission routes. Authoring facts and scope: research/admissions-120/requirements.json. Optional, backward-compatible layer. */\nwindow.UNIPATH.admissionRequirements = '+json.dumps({k:v['routes'] for k,v in records.items()},ensure_ascii=False,indent=2)+';\n',encoding='utf8')
 (OUT/'reviews.json').write_text(json.dumps(reviews,ensure_ascii=False,indent=2)+'\n',encoding='utf8');flush_ru()
 # flush() only adds absent keys. Repair accidental English identity entries
 # from this follow-up without overwriting any existing Russian translation.
 p=Path('data/i18n/ru.js');dictionary=p.read_text(encoding='utf8')
 for key,value in TR.items():
  if key!=value:
   dictionary=dictionary.replace('  '+json.dumps(key,ensure_ascii=False)+': '+json.dumps(key,ensure_ascii=False)+',','  '+json.dumps(key,ensure_ascii=False)+': '+json.dumps(value,ensure_ascii=False)+',')
 p.write_text(dictionary,encoding='utf8')
if __name__=='__main__':
 # Published Provost procedure explicitly includes undergraduate applicants;
 # 7.0 concerns post-admission placement, not the admission minimum.
 pitt=records['university-of-pittsburgh']['routes'][0]
 pitt['english']={'requirement':'required-unless-exempt','ielts':{'accepted':True,'min':6.5,'role':'admission'},'toefl':{'accepted':True,'scales':[{'period':'legacy','min':80}]},'waiver':L('The Provost procedure permits proof through citizenship of a country with English as an official language, a degree at a regionally accredited US institution, or a degree taught in English in a country whose official national language is English. Exceptions need Provost approval.','Правила Provost допускают подтверждение гражданством страны с официальным английским, дипломом регионально аккредитованного вуза США либо дипломом на английском в стране с официальным национальным английским. Исключения требуют одобрения Provost.'),'note':L('The active Provost procedure publishes baseline IELTS 6.5 and legacy TOEFL iBT 80. Below IELTS 7.0 / TOEFL 100, admitted undergraduates take an additional English placement test. Schools may require higher scores: Nursing policy revised August 2025 states IELTS 7.5, Speaking 7 and other sections 6. These are not universal thresholds. The procedure has a 2010 revision date and no named 2027 intake.','Действующая процедура Provost публикует базовые IELTS 6,5 и TOEFL iBT 80 по прежней шкале. При IELTS ниже 7,0 / TOEFL ниже 100 принятые бакалавры проходят дополнительный языковой тест распределения. Школы могут требовать больше: Nursing, редакция августа 2025, указывает IELTS 7,5, Speaking 7 и остальные секции 6. Эти повышенные пороги не универсальны. Процедура имеет дату редакции 2010 и не называет набор 2027.')}
 for u,label,ru in [('https://www.provost.pitt.edu/assessment-english-language-proficiency-procedure','Pittsburgh: undergraduate scope of Provost language procedure','Pittsburgh: языковые правила Provost для бакалавриата'),('https://www.nursing.pitt.edu/policies/365/','Pittsburgh Nursing: programme-specific language exception','Pittsburgh Nursing: особые языковые требования программы')]:pitt['sources'].append(S(u,L(label,ru)))
 reviews['university-of-pittsburgh']={'id':'university-of-pittsburgh','country':'us','status':'language-baseline-established','source':pitt['sources'][-2]['url'],'checked':'2026-11-19','change':'Established undergraduate English proof, baseline and placement distinction; Nursing exception stays school-specific.','remaining':'Current school-specific and Fall 2027 language rules, IELTS variant/sections for the general route and new TOEFL scale remain unestablished.'}
 records['university-of-pittsburgh']['unknown']=[reviews['university-of-pittsburgh']['remaining']]
 # The current undergraduate page uses SAT/ACT to satisfy English proof;
 # the displayed IELTS 6.0 table is explicitly the 60+ credit transfer route.
 w=records['university-of-west-florida']['routes'][0]
 w['english']={'requirement':'alternatives-with-academic','ielts':{'accepted':None,'min':None},'note':L('For international freshmen (0–11 college credits), the admissions page says English proficiency is met by ACT or SAT admission-test requirements. Its IELTS 6.0 / TOEFL table is for transfer applicants with 60+ credits, not a verified freshman IELTS alternative. Regulation 3.042 lists broader English-proof options; their application to an individual freshman must be confirmed.','Для иностранных первокурсников (0–11 кредитов колледжа) страница приёма говорит о подтверждении английского через требования ACT или SAT. Таблица IELTS 6,0 / TOEFL относится к переводящимся с 60+ кредитами и не подтверждает IELTS как альтернативу первокурсника. Regulation 3.042 перечисляет более широкие варианты английского; их применимость к конкретному первокурснику нужно уточнить.')}
 academic('university-of-west-florida','Freshmen submit secondary records and credential evaluation. SAT, ACT or CLT admission-score rules apply; the page links Regulations 3.001 and 3.042. An English-test table for 60+ transfer credits is not a freshman admission route.','Первокурсники подают школьные документы и оценку квалификации. Действуют правила вступительных баллов SAT, ACT либо CLT; страница ссылается на Regulations 3.001 и 3.042. Таблица языковых экзаменов для перевода с 60+ кредитами не является маршрутом первокурсника.','https://uwf.edu/admissions/undergraduate/apply/international/requirements/','UWF: international undergraduate requirements by credit category','Exact current admission-test section thresholds, any freshman IELTS-only exception and Fall 2027-specific revision remain to be established.',policy='required-alternatives')
 # Le Moyne's international page places 6.5 under GRADUATE admission.
 academic('le-moyne-college','First-year checklist: application, essay, one academic recommendation and official secondary transcript. SAT/ACT are explicitly optional on the current undergraduate application page. The international page puts IELTS 6.5 under graduate admission, so it is not copied to this bachelor route.','Список первокурсника: заявка, эссе, одна академическая рекомендация и официальный школьный транскрипт. На действующей бакалаврской странице SAT/ACT прямо названы необязательными. Международная страница помещает IELTS 6,5 в раздел магистратуры; на бакалавриат он не переносится.','https://www.lemoyne.edu/admission-financial-aid/apply/','Le Moyne: first-year required and optional materials','A current international undergraduate English-proof checklist, numerical minima, section rules and waiver conditions are still needed; graduate IELTS 6.5 is not evidence.',policy='optional',status='language-open-academics-established')
 academic('university-of-the-pacific','Secondary completion and all school/college transcripts are required. Admissions Test Scores says SAT/ACT optional, including direct-admit international applicants; the active academic catalogue still says freshmen must submit them. Neither source establishes which rule governs Fall 2027.','Нужны окончание средней школы и все школьные/вузовские транскрипты. Admissions Test Scores называет SAT/ACT необязательными, в том числе для прямого международного приёма; действующий академический каталог по-прежнему требует их от первокурсников. Ни один источник не устанавливает, какое правило действует на Fall 2027.','https://catalog.pacific.edu/uop/generalinformation/admissionrequirements/','Pacific: academic catalogue freshman checklist','Admission must resolve the conflict between the catalogue and the Test Scores page for the selected programme/intake; no confirmed SAT waiver is used.',policy='conflict',status='conflict-retained')
 academic('stockton-university','Secondary completion, translated records and qualification evaluation are required. Admissions permits test-optional outside Accelerated Medical, Pharmacy and Nursing. Global Engagement additionally requires SAT/ACT for applicants from English-speaking educational countries. The overlapping applicant scope remains contradictory.','Нужны окончание средней школы, переведённые документы и оценка квалификации. Admissions допускает подачу без тестов, кроме Accelerated Medical, Pharmacy и Nursing. Global Engagement дополнительно требует SAT/ACT от кандидатов из англоязычной образовательной среды. В пересекающейся категории источники остаются противоречивыми.','https://stockton.edu/admissions/test-optional.html','Stockton: test-optional programme exceptions','Admissions must clarify the English-speaking-applicant requirement versus test-optional and the exact chosen specialty. The undated pages do not explicitly confirm Fall 2027.',policy='conflict',status='conflict-retained')
 academic('saint-marys-college-indiana','International applicants submit translated detailed secondary records, a recommendation, essay and financial certification. The catalogue specifically allows non-native English speakers to submit TOEFL, IELTS or Duolingo instead of SAT; its general testing paragraph retains an international-test exception. A separate mandatory SAT is not inferred for applicants using the named language-test alternative.','Иностранцы подают подробные переведённые школьные документы, рекомендацию, эссе и финансовое подтверждение. Каталог отдельно разрешает кандидатам с неродным английским TOEFL, IELTS или Duolingo вместо SAT; общий раздел сохраняет исключение о тестах иностранцев. Отдельный обязательный SAT для выбравших указанную языковую альтернативу не выводится.','https://catalog.saintmarys.edu/undergraduate/admission/','Saint Mary’s Indiana: international checklist and testing exceptions','The exact applicant language category, programme and selected-cycle requirements must be confirmed; catalogue and international-page score guidance are not universal admission cutoffs.',policy='conditional')
 academic('john-jay-college','International freshmen submit secondary transcripts, graduation diplomas and official English translations directly to CUNY; this checklist says external evaluations are not required. It strongly recommends SAT/ACT for non-English-country applicants or those without school Math/English; a recommendation is not a mandatory test rule.','Иностранные первокурсники подают в CUNY школьные транскрипты, дипломы об окончании и официальные английские переводы; этот список не требует внешней оценки. SAT/ACT настоятельно рекомендуются кандидатам из неанглоязычных стран либо без школьных Math/English; рекомендация не является обязательным тестовым правилом.','https://www.jjay.cuny.edu/admissions/undergraduate-admissions/apply/international-student-application','John Jay: international freshman academic documents','The exact Fall 2027 CUNY-wide score-consideration policy and programme-specific exceptions need the current CUNY applicant guide.',policy='accepted')
 academic('milwaukee-school-of-engineering','Official secondary records are required. Pre-calculus or higher, Physics and Chemistry form the recommended preparation; 3.2 cumulative GPA is recommended, not an automatic eligibility guarantee. SAT/ACT are optional initially, but available scores may be requested after academic review.','Нужны официальные школьные документы. Pre-calculus или выше, Physics и Chemistry — рекомендуемая подготовка; общий GPA 3,2 рекомендован и не гарантирует допуск. SAT/ACT необязательны в начальной заявке, но доступные баллы могут запросить после академического рассмотрения.','https://www.msoe.edu/admissions-aid/undergraduate-admissions/undergraduate-admission-requirements/','MSOE: preparation and test-optional first-year review','Exact programme prerequisites, any individual request for scores and the named Fall 2027 cycle remain applicant-specific.',policy='optional')
 academic('manhattan-university','First-year applicants submit an official secondary transcript, recommendation and essay. SAT/ACT are explicitly optional; academic record and chosen-programme preparation remain part of holistic review. English-proof alternatives on the international page are a separate requirement.','Первокурсники подают официальный школьный транскрипт, рекомендацию и эссе. SAT/ACT прямо названы необязательными; академическая подготовка к выбранной программе остаётся частью комплексного рассмотрения. Альтернативы английского международной страницы — отдельное требование.','https://manhattan.edu/admissions/undergraduate/requirements','Manhattan: first-year academic application requirements','Specific programme prerequisites and named Fall 2027 applicability remain to be confirmed; English waiver conditions require individual assessment.',policy='optional')
 finish()
